/* static/css/style.css */

/* General Styles */
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    background-color: #f4f4f9;
    color: #333;
}

/* Header */
header {
    background-color: #6200ea;
    color: #fff;
    padding: 1rem 2rem;
    text-align: center;
}

header h1 {
    margin: 0;
    font-size: 2rem;
}

/* Navigation */
nav {
    background-color: #3700b3;
    padding: 0.5rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

nav a {
    color: #fff;
    text-decoration: none;
    margin: 0 1rem;
    font-weight: bold;
}

nav a:hover {
    text-decoration: underline;
}

/* Main Content */
main {
    padding: 2rem;
    margin: 0 auto;
    max-width: 800px;
    background: #fff;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

/* Forms */
form {
    margin: 1.5rem 0;
}

form input,
form textarea,
form select,
form button {
    display: block;
    width: 100%;
    padding: 0.8rem;
    margin: 1rem 0;
    border: 1px solid #ddd;
    border-radius: 4px;
}

form button {
    background-color: #6200ea;
    color: #fff;
    border: none;
    cursor: pointer;
    font-size: 1rem;
}

form button:hover {
    background-color: #3700b3;
}

/* Notes List */
.note {
    background: #fff;
    border-left: 4px solid #6200ea;
    margin: 1.5rem 0;
    padding: 1rem;
    border-radius: 4px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

.note h2 {
    margin: 0 0 0.5rem;
    font-size: 1.5rem;
}

.note p {
    margin: 0;
}

/* Footer */
footer {
    text-align: center;
    padding: 1rem;
    background-color: #6200ea;
    color: #fff;
    margin-top: 2rem;
}

footer p {
    margin: 0;
    font-size: 0.9rem;
}

// static/js/app.js

// Function to make an API request
async function fetchAPI(endpoint, method = 'GET', data = null) {
    const options = {
        method: method,
        headers: {
            'Content-Type': 'application/json',
        },
    };

    if (data) {
        options.body = JSON.stringify(data);
    }

    try {
        const response = await fetch(endpoint, options);
        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }
        return response.json();
    } catch (error) {
        console.error('Error fetching API:', error);
        throw error;
    }
}

// Function to handle note creation
async function createNote() {
    const title = document.getElementById('note-title').value;
    const content = document.getElementById('note-content').value;

    if (!title || !content) {
        alert('Title and content cannot be empty!');
        return;
    }

    try {
        const response = await fetchAPI('/api/notes', 'POST', {
            title: title,
            content: content,
        });
        alert('Note created successfully!');
        window.location.reload();
    } catch (error) {
        alert('Failed to create note. Please try again.');
    }
}

// Function to search notes
async function searchNotes() {
    const query = document.getElementById('search-query').value;

    try {
        const results = await fetchAPI(`/api/notes/search?q=${encodeURIComponent(query)}`);
        renderNotes(results);
    } catch (error) {
        alert('Failed to search notes. Please try again.');
    }
}

// Function to render notes on the page
function renderNotes(notes) {
    const notesContainer = document.getElementById('notes-container');
    notesContainer.innerHTML = '';

    if (notes.length === 0) {
        notesContainer.innerHTML = '<p>No notes found.</p>';
        return;
    }

    notes.forEach(note => {
        const noteElement = document.createElement('div');
        noteElement.className = 'note';
        noteElement.innerHTML = `
            <h3>${note.title}</h3>
            <p>${note.content}</p>
        `;
        notesContainer.appendChild(noteElement);
    });
}

// Event listeners
document.getElementById('create-note-btn').addEventListener('click', createNote);
document.getElementById('search-btn').addEventListener('click', searchNotes);

from flask import Blueprint, render_template, request, redirect, url_for, flash
from app.database import db
from app.models.problem import Problem

problem_bp = Blueprint('problem', __name__)

@problem_bp.route('/problems', methods=['GET'])
def list_problems():
    """Fetch and display all problems."""
    problems = Problem.query.all()
    return render_template('problem.html', problems=problems)

@problem_bp.route('/problems/<int:problem_id>', methods=['GET'])
def get_problem(problem_id):
    """Fetch and display a specific problem by ID."""
    problem = Problem.query.get_or_404(problem_id)
    return render_template('problem.html', problem=problem)

@problem_bp.route('/problems/new', methods=['GET', 'POST'])
def create_problem():
    """Create a new problem."""
    if request.method == 'POST':
        title = request.form.get('title')
        description = request.form.get('description')

        if not title or not description:
            flash('Title and Description are required!', 'error')
            return redirect(url_for('problem.create_problem'))

        new_problem = Problem(title=title, description=description)
        db.session.add(new_problem)
        db.session.commit()

        flash('Problem created successfully!', 'success')
        return redirect(url_for('problem.list_problems'))

    return render_template('submit.html')

@problem_bp.route('/problems/<int:problem_id>/edit', methods=['GET', 'POST'])
def edit_problem(problem_id):
    """Edit an existing problem."""
    problem = Problem.query.get_or_404(problem_id)

    if request.method == 'POST':
        title = request.form.get('title')
        description = request.form.get('description')

        if not title or not description:
            flash('Title and Description are required!', 'error')
            return redirect(url_for('problem.edit_problem', problem_id=problem_id))

        problem.title = title
        problem.description = description
        db.session.commit()

        flash('Problem updated successfully!', 'success')
        return redirect(url_for('problem.list_problems'))

    return render_template('submit.html', problem=problem)

@problem_bp.route('/problems/<int:problem_id>/delete', methods=['POST'])
def delete_problem(problem_id):
    """Delete a specific problem."""
    problem = Problem.query.get_or_404(problem_id)
    db.session.delete(problem)
    db.session.commit()

    flash('Problem deleted successfully!', 'success')
    return redirect(url_for('problem.list_problems'))

from flask import Blueprint, render_template, request, redirect, url_for, flash
from app.database import db
from app.models.user import User

user_bp = Blueprint('user', __name__)

@user_bp.route('/users', methods=['GET'])
def list_users():
    """Handles GET requests to list all users."""
    try:
        users = User.query.all()
        return render_template('users/list.html', users=users)
    except Exception as e:
        flash(f"Error fetching users: {str(e)}", "danger")
        return render_template('problem.html')

@user_bp.route('/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Handles GET requests to retrieve a specific user."""
    try:
        user = User.query.get_or_404(user_id)
        return render_template('users/detail.html', user=user)
    except Exception as e:
        flash(f"Error fetching user: {str(e)}", "danger")
        return render_template('problem.html')

@user_bp.route('/users/new', methods=['GET', 'POST'])
def create_user():
    """Handles GET and POST requests to create a new user."""
    if request.method == 'POST':
        try:
            username = request.form['username']
            email = request.form['email']
            new_user = User(username=username, email=email)
            db.session.add(new_user)
            db.session.commit()
            flash("User created successfully!", "success")
            return redirect(url_for('user.list_users'))
        except Exception as e:
            db.session.rollback()
            flash(f"Error creating user: {str(e)}", "danger")
    return render_template('users/new.html')

@user_bp.route('/users/<int:user_id>/edit', methods=['GET', 'POST'])
def edit_user(user_id):
    """Handles GET and POST requests to edit a user."""
    user = User.query.get_or_404(user_id)
    if request.method == 'POST':
        try:
            user.username = request.form['username']
            user.email = request.form['email']
            db.session.commit()
            flash("User updated successfully!", "success")
            return redirect(url_for('user.list_users'))
        except Exception as e:
            db.session.rollback()
            flash(f"Error updating user: {str(e)}", "danger")
    return render_template('users/edit.html', user=user)

@user_bp.route('/users/<int:user_id>/delete', methods=['POST'])
def delete_user(user_id):
    """Handles POST requests to delete a user."""
    try:
        user = User.query.get_or_404(user_id)
        db.session.delete(user)
        db.session.commit()
        flash("User deleted successfully!", "success")
        return redirect(url_for('user.list_users'))
    except Exception as e:
        db.session.rollback()
        flash(f"Error deleting user: {str(e)}", "danger")
        return redirect(url_for('user.list_users'))

from flask import Blueprint, request, jsonify, render_template, redirect, url_for
from app.database import db
from app.models.solution import Solution
from app.models.problem import Problem
from app.models.user import User

solution_bp = Blueprint('solution', __name__)

@solution_bp.route('/solutions', methods=['GET'])
def list_solutions():
    """List all solutions."""
    solutions = Solution.query.all()
    return render_template('solutions/index.html', solutions=solutions)

@solution_bp.route('/solutions/<int:solution_id>', methods=['GET'])
def get_solution(solution_id):
    """Get a specific solution by ID."""
    solution = Solution.query.get_or_404(solution_id)
    return render_template('solutions/show.html', solution=solution)

@solution_bp.route('/solutions/new', methods=['GET', 'POST'])
def create_solution():
    """Create a new solution."""
    if request.method == 'POST':
        content = request.form['content']
        problem_id = request.form['problem_id']
        user_id = request.form['user_id']

        # Validate problem and user existence
        problem = Problem.query.get(problem_id)
        user = User.query.get(user_id)
        if not problem or not user:
            return jsonify({'error': 'Invalid problem or user ID'}), 400

        solution = Solution(content=content, problem_id=problem_id, user_id=user_id)
        db.session.add(solution)
        db.session.commit()
        return redirect(url_for('solution.list_solutions'))

    problems = Problem.query.all()
    users = User.query.all()
    return render_template('solutions/new.html', problems=problems, users=users)

@solution_bp.route('/solutions/<int:solution_id>/edit', methods=['GET', 'POST'])
def edit_solution(solution_id):
    """Edit an existing solution."""
    solution = Solution.query.get_or_404(solution_id)

    if request.method == 'POST':
        solution.content = request.form['content']
        db.session.commit()
        return redirect(url_for('solution.get_solution', solution_id=solution.id))

    return render_template('solutions/edit.html', solution=solution)

@solution_bp.route('/solutions/<int:solution_id>/delete', methods=['POST'])
def delete_solution(solution_id):
    """Delete a solution by ID."""
    solution = Solution.query.get_or_404(solution_id)
    db.session.delete(solution)
    db.session.commit()
    return redirect(url_for('solution.list_solutions'))
